#!/usr/bin/env python3

import antlr4 as a4

# automatically trigger ANTLR4 Java tool, if we fail to import the files
# generated by it
try:
    from gelb.antlr4.generated_code import (
        GeLBLexer,
        GeLBParser,
        GeLBVisitor
    )
except ModuleNotFoundError:
    from gelb.utils.misc import invoke_antlr4_tool
    invoke_antlr4_tool()
    from gelb.antlr4.generated_code import (
        GeLBLexer,
        GeLBParser,
        GeLBVisitor
    )

from gelb.ASTBuilderVisitor import ASTBuilderVisitor
from gelb.ParsingError import ParsingError
from gelb.utils.misc import ensure_file_is_not_empty_or_whitespace
from gelb.utils.compiler_complaints import *


def get_cst_as_string(start_rule, input_string):
    input_stream = a4.InputStream(input_string)
    lexer = GeLBLexer(input_stream)
    token_stream = a4.CommonTokenStream(lexer)
    token_stream.fill()
    parser = GeLBParser(token_stream)
    parser.removeErrorListeners()
    parser.addErrorListener(ParsingError())

    if hasattr(parser, start_rule):
        func_start_rule = getattr(parser, start_rule)
        cst = func_start_rule()
        return cst.toStringTree(recog=parser)
    else:
        complain_about_invalid_grammar_rule(start_rule)


def get_ast(start_rule, input_string, verbose=False):
    ensure_file_is_not_empty_or_whitespace(input_string, verbose)

    input_stream = a4.InputStream(input_string)
    lexer = GeLBLexer(input_stream)
    token_stream = a4.CommonTokenStream(lexer)
    token_stream.fill()
    parser = GeLBParser(token_stream)
    parser.removeErrorListeners()
    parser.addErrorListener(ParsingError())

    if hasattr(parser, start_rule):
        func_start_rule = getattr(parser, start_rule)
        cst = func_start_rule()
        ast_builder = ASTBuilderVisitor()
        visitor_method_name = f"visit{start_rule.capitalize()}"
        if hasattr(ast_builder, visitor_method_name):
            # TODO: trigger creation of (sub-)AST & return
            visitor_method = getattr(ast_builder, visitor_method_name)
            ast = visitor_method(cst)
            return ast
        else:
            complain_about_missing_visitor_method(start_rule,
                                                  visitor_method_name)
    else:
        complain_about_invalid_grammar_rule(start_rule)
